def _row(t):
    n,mk,fit,lic,dat,ch,unit,p,c,ppl,goal = t
    m = p - c
    pct = round(100*m/p) if p else 0
    s = n.lower()
    return [
    (f"Study who buys {s} here: {mk}. Count buyers, ask 10 and note why they would pay.",
     f"Example: call 10 buyers this week and log the budget, timing and the one blocker each names."),
    (f"Test fit: {fit}. Score your skills against the local need.",
     f"Example: list 3 strengths and 3 gaps for {s}, then pick one niche in the city to start."),
    (f"Choose your set-up: {lic}. Pick a local company type and register the business early.",
     f"Example: write a one-page rule list for {s} with a date to check each item with a professional."),
    (f"Follow Hong Kong data law in plain words: {dat}.",
     f"Example: draft a short notice for {s}: what you collect, why, how long, who sees it."),
    (f"Find customers through {ch}. Use Chinese and English and message on WhatsApp.",
     f"Example: post one bilingual offer for {s} and book 5 calls from replies."),
    (f"Price in HKD: one {unit} sells at HKD {p:,} with cost HKD {c:,}, so margin is HKD {m:,} ({pct}%). Profits tax applies to profit; there is no sales tax; check current rate.",
     f"Example: at 40 sales a month, margin is HKD {m*40:,}; compare it with rent and pay."),
    (f"Plan people: {ppl}. Check MPF (a pension scheme for staff), minimum wage and leave rules.",
     f"Example: write 2 roles for {s} with hours, pay and a trial month; check MPF steps."),
    (f"Launch small. Go/no-go rule: {goal}. If not met in 90 days, stop or change.",
     f"Example: set a 90-day board for {s} with 3 numbers and a stop date."),
    ]

R_hk_2 = {t[0]: _row(t) for t in _T}
